import csv
import matplotlib.pyplot as plt

x_vals = []
y_vals = []

# Read the CSV data generated by your simulation
with open('orbit_data.csv', mode='r') as file:
    reader = csv.DictReader(file)
    for row in reader:
        x_vals.append(float(row['X']))
        y_vals.append(float(row['Y']))

# Plot the orbit
plt.figure(figsize=(6, 6))
plt.plot(x_vals, y_vals, color='cyan', label='Star S0-2 Orbit', linewidth=2)
plt.scatter([0], [0], color='orange', s=300, marker='o', label='Sagittarius A*') # The Black Hole at the center

# Styling the graph
plt.title("Orbital Mechanics Simulation Around Sagittarius A*")
plt.xlabel("X Position (Parsecs)")
plt.ylabel("Y Position (Parsecs)")
plt.legend()
plt.grid(True, linestyle='--', alpha=0.6)
plt.axhline(0, color='gray', linewidth=0.8)
plt.axvline(0, color='gray', linewidth=0.8)

# Show the interactive plot window
plt.show()